// ============================================================
// Hifzhelper — Quran structural data
// ============================================================
// This is the ONE place this data lives (see CONVENTIONS.md, principle 2).
// It is static — the Quran's structure doesn't change — so hardcoding it is
// correct. What matters is that it exists in exactly one file, loaded by
// both the frontend (as a plain script, for file:// portability — see
// CONVENTIONS.md on why this isn't an ES module) and the Worker (via
// require(), since Workers bundled with wrangler support CommonJS).
//
// Do not copy any of this into app.js or the Worker. Import/require this
// file instead.

// Each tag carries its own major/minor classification — major mistakes are
// a hard veto on a gamified ring closing, regardless of the numeric
// mistake count; minor tags just add to that count. This is a property of
// the tag itself, decided once here, not a per-instance judgment call.
// The three majors are the classical tajweed error taxonomy (substitution/
// omission/addition) — different maktabs may use different terminology
// for these later, but this is the starting default.
const TAJWEED_DEFAULTS = [
  { tag: 'Substitution', major: true },
  { tag: 'Omission', major: true },
  { tag: 'Addition', major: true },
  { tag: 'Ghunnah', major: false },
  { tag: 'Qalqalah', major: false },
  { tag: 'Madd', major: false },
  { tag: 'Idgham', major: false },
  { tag: 'Ikhfa', major: false },
  { tag: 'Noon Sakinah', major: false },
  { tag: 'Meem Sakinah', major: false },
  { tag: 'Waqf', major: false }
];

