// Given a surah + ayah range, returns how many lines and pages it spans in the
// 13-line print. Approximate by design (see LINE13_RANGES source note above) —
// good enough for counting, not precise enough to claim an exact ayah:page reference.
function getLines13ForAyahRange(surah, ayahFrom, ayahTo){
  const from = ayahFrom||1, to = ayahTo||ayahFrom||1;
  let lo = null, hi = null;
  for(const [s,a,first,last] of AYAH_WORD_RANGE){
    if(s===surah && a>=Math.min(from,to) && a<=Math.max(from,to)){
      if(lo===null || first<lo) lo = first;
      if(hi===null || last>hi) hi = last;
    }
  }
  if(lo===null) return null;
  const touched = LINE13_RANGES.filter(([p,l,f,lw]) => !(lw<lo || f>hi));
  const pages = [...new Set(touched.map(([p]) => p))];
  return { lineCount: touched.length, pageCount: pages.length, pages };
}

